(function(root,factory){"use strict";var api=factory();if(typeof module==="object"&&module.exports)module.exports=api;else api.init(root.document,root)})(typeof window!=="undefined"?window:this,function(){"use strict";var defaults={distancia:"1,42",rua:"true",trail:"true",nacional:"true",internacional:"false",cupom:"false",badges:""};function values(href){var url=new URL(href),out={};Object.keys(defaults).forEach(function(k){out[k]=url.searchParams.get(k)||defaults[k]});return out}function preset(currentHref,presetHref){var target=new URL(presetHref,currentHref),filters=values(currentHref);target.searchParams.delete("pagina");target.searchParams.delete("tempo");Object.keys(filters).forEach(function(k){if(filters[k]!==defaults[k])target.searchParams.set(k,filters[k]);else target.searchParams.delete(k)});return target.pathname+target.search}function init(document,window2){var form=document.querySelector("[data-regional-period-form]");if(!form)return;var first=form.querySelector('[name="periodo_inicio"]'),last=form.querySelector('[name="periodo_fim"]');function validate(){last.setCustomValidity(last.value&&first.value&&last.value<first.value?"A data final deve ser igual ou posterior \xE0 inicial.":"")}first.addEventListener("input",validate);last.addEventListener("input",validate);form.addEventListener("submit",function(){var filters=values(window2.location.href);Object.keys(filters).forEach(function(k){form.querySelector('[name="'+k+'"]').value=filters[k]})});document.querySelectorAll("[data-regional-period-link]").forEach(function(a){a.addEventListener("click",function(){a.href=preset(window2.location.href,a.href)})})}return{values,preset,init}});
